part of 'litert_lm_v1_runtime.dart';

/// Internal per-send decode overrides; omitted values preserve native defaults.
///
/// These do not change the conversation sampler or seed. Penalties count only
/// tokens generated by this send. Thinking budgets require first-channel
/// boundary/tokenization admission and remain isolated to this send.
final class LiteRtLmV1TurnSettings {
  /// Creates immutable overrides without applying GenerationParams defaults.
  const LiteRtLmV1TurnSettings({
    this.maxOutputTokens,
    this.visualTokenBudget,
    this.repetitionPenalty,
    this.presencePenalty,
    this.thinkingTokenBudget,
    this.jsonSchema,
  });

  /// Positive signed C-int total output cap, including any reasoning tokens.
  final int? maxOutputTokens;

  /// Explicit positive Gemma4 image budget; refused for other processors.
  final int? visualTokenBudget;

  /// Finite native float at least 1, or null for no repetition penalty.
  final double? repetitionPenalty;

  /// Finite native float; negative values reward repetition.
  final double? presencePenalty;

  /// Positive signed C-int budget for an admitted first reasoning channel.
  final int? thinkingTokenBudget;

  /// JSON Schema for a conversation explicitly created with constraints enabled.
  final String? jsonSchema;

  bool get _hasPenalties =>
      repetitionPenalty != null || presencePenalty != null;
  bool get _hasArgs =>
      maxOutputTokens != null ||
      visualTokenBudget != null ||
      _hasPenalties ||
      jsonSchema != null ||
      thinkingTokenBudget != null;

  void _validate(LiteRtLmV1Runtime runtime, {String? extraContext}) {
    if (jsonSchema case final schema?) {
      if (schema.isEmpty || schema.contains('\u0000')) {
        throw LlamaArgumentException(
          'C API 1.0 JSON Schema must be nonempty without NUL.',
        );
      }
      try {
        final decoded = jsonDecode(schema);
        if (decoded is! Map && decoded is! bool) {
          throw const FormatException();
        }
      } on FormatException {
        throw LlamaArgumentException(
          'C API 1.0 JSON Schema must be a JSON object or boolean.',
        );
      }
      _V1JsonSchema(runtime).requireSupport();
    }
    if (thinkingTokenBudget case final budget?) {
      if (budget <= 0 || budget > 0x7fffffff) {
        throw LlamaArgumentException(
          'Thinking token budget must be a positive signed C int.',
        );
      }
      if (jsonSchema != null || runtime._conversation?._schemaEnabled == true) {
        throw LlamaUnsupportedException(
          'C API 1.0 schema chat cannot also enforce a thinking budget.',
        );
      }
      if (runtime._engineSpeculativeDecoding) {
        throw LlamaUnsupportedException(
          'C API 1.0 thinking budgets with speculative decoding are not qualified.',
        );
      }
      _V1ThinkingBudget(runtime).admit(extraContext: extraContext);
    }
    if (maxOutputTokens case final limit?) {
      if (limit <= 0 || limit > 0x7fffffff) {
        throw LlamaArgumentException(
          'C API 1.0 per-turn maxOutputTokens must be a positive signed C int.',
        );
      }
    }
    if (visualTokenBudget case final budget?) {
      if (budget <= 0 || budget > 0x7fffffff) {
        throw LlamaArgumentException(
          'Visual token budget must be a positive signed C int.',
        );
      }
      if (!runtime._inspectMediaSupport().visualBudget) {
        throw LlamaUnsupportedException(
          'C API 1.0 visual token budgets require a declared Gemma4 image processor and its native setter export.',
        );
      }
    }
    for (final value in [?repetitionPenalty, ?presencePenalty]) {
      if (!value.isFinite ||
          value.abs() > 3.4028234663852886e38 ||
          (value != 0 && Float32List.fromList([value]).single == 0)) {
        throw LlamaArgumentException(
          'C API 1.0 penalties must be finite native floats without nonzero underflow.',
        );
      }
    }
    if (repetitionPenalty != null && repetitionPenalty! < 1) {
      throw LlamaUnsupportedException(
        'C API 1.0 repetitionPenalty must be at least 1; native execution clamps smaller values.',
      );
    }
    if (_hasPenalties && runtime._engineSpeculativeDecoding) {
      throw LlamaUnsupportedException(
        'C API 1.0 penalties with speculative decoding are not qualified.',
      );
    }
    if (!_hasArgs) return;
    final symbols = <String>[
      'litert_lm_conversation_optional_args_create',
      'litert_lm_conversation_optional_args_delete',
      if (maxOutputTokens != null)
        'litert_lm_conversation_optional_args_set_max_output_tokens',
      if (visualTokenBudget != null)
        'litert_lm_conversation_optional_args_set_visual_token_budget',
      if (_hasPenalties) ...[
        'litert_lm_repetition_penalty_config_create',
        'litert_lm_repetition_penalty_config_delete',
        'litert_lm_repetition_penalty_config_set_repetition_penalty',
        'litert_lm_repetition_penalty_config_set_presence_penalty',
        'litert_lm_conversation_optional_args_set_repetition_penalty_config',
      ],
    ];
    for (final symbol in symbols) {
      if (!runtime._library.providesSymbol(symbol)) {
        throw LlamaUnsupportedException(
          'C API 1.0 per-turn options require native export $symbol.',
        );
      }
    }
  }

  Pointer<Void> _createArgs(LiteRtLmV1Runtime runtime) {
    if (!_hasArgs) return nullptr;
    final library = runtime._library;
    final deleteArgs = library.lookupFunction<_DeleteN, _DeleteD>(
      'litert_lm_conversation_optional_args_delete',
    );
    final output = calloc<Pointer<Void>>();
    Pointer<Void> args = nullptr;
    try {
      final status = library.lookupFunction<_CreateN, _CreateD>(
        'litert_lm_conversation_optional_args_create',
      )(output);
      args = output.value;
      runtime._check(status, 'conversation_optional_args_create');
      if (args == nullptr) {
        throw LlamaStateException(
          'conversation_optional_args_create reported success without an owned handle.',
        );
      }
      if (maxOutputTokens case final limit?) {
        runtime._check(
          library.lookupFunction<_SetIntN, _SetIntD>(
            'litert_lm_conversation_optional_args_set_max_output_tokens',
          )(args, limit),
          'optional_args_set_max_output_tokens',
        );
      }
      if (visualTokenBudget case final budget?) {
        runtime._check(
          library.lookupFunction<_SetIntN, _SetIntD>(
            'litert_lm_conversation_optional_args_set_visual_token_budget',
          )(args, budget),
          'optional_args_set_visual_token_budget',
        );
      }
      if (_hasPenalties) {
        final deletePenalty = library.lookupFunction<_DeleteN, _DeleteD>(
          'litert_lm_repetition_penalty_config_delete',
        );
        final penalty = runtime._create(
          'repetition_penalty_config_create',
          library.lookupFunction<_CreateN, _CreateD>(
            'litert_lm_repetition_penalty_config_create',
          ),
        );
        try {
          runtime._check(
            library.lookupFunction<_SetFloatN, _SetFloatD>(
              'litert_lm_repetition_penalty_config_set_repetition_penalty',
            )(penalty, repetitionPenalty ?? 1),
            'penalty_set_repetition_penalty',
          );
          runtime._check(
            library.lookupFunction<_SetFloatN, _SetFloatD>(
              'litert_lm_repetition_penalty_config_set_presence_penalty',
            )(penalty, presencePenalty ?? 0),
            'penalty_set_presence_penalty',
          );
          runtime._check(
            library.lookupFunction<_SetPointerN, _SetPointerD>(
              'litert_lm_conversation_optional_args_set_repetition_penalty_config',
            )(args, penalty),
            'optional_args_set_repetition_penalty_config',
          );
        } finally {
          deletePenalty(penalty);
        }
      }
      if (jsonSchema case final schema?) {
        _V1JsonSchema(runtime).constrain(
          args,
          schema,
          thinking: runtime._conversation?._schemaThinking ?? false,
        );
      }
      if (thinkingTokenBudget case final budget?) {
        _V1ThinkingBudget(runtime).apply(args, budget);
      }
      return args;
    } on Object {
      if (args != nullptr) deleteArgs(args);
      rethrow;
    } finally {
      calloc.free(output);
    }
  }
}
